'use strict';
const data=window.BENCHMARK;
const $=s=>document.querySelector(s);
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const pct=v=>(100*v).toFixed(1)+'%';
const n=v=>v.toLocaleString('en-US');
const metric=(label,value,note='',gold=false)=>`<div class="metric ${gold?'gold':''}"><label>${label}</label><strong>${value}</strong><small>${note}</small></div>`;
const date=day=>new Date(Date.UTC(2025,0,day+1)).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
let current='forecast',category='All categories',threshold=.3,cost=4;
const views={forecast:['A clearer view of spend.','Compare a frozen 28-day forecast with a weekly baseline, then inspect what the model missed.'],customers:['Find the quiet signals.','Rank customers by next-30-day inactivity risk. Change the review threshold and export the full selected cohort.'],experiment:['Would the intervention pay?','Use a separate randomized experiment to estimate incremental spend and test campaign economics.'],methods:['Make every result inspectable.','Fixed seeds, explicit time boundaries, simple baselines, and a runnable Python pipeline.']};
function chart(s){
 const W=960,H=270,L=60,R=18,T=15,B=35,first=216,last=299;
 const vals=s.daily.slice(first);const max=Math.max(...vals,...s.prediction.map(v=>v+s.band_width))*1.07;
 const x=d=>L+(d-first)/(last-first)*(W-L-R),y=v=>H-B-v/max*(H-T-B);
 const path=(arr,start)=>arr.map((v,i)=>`${i?'L':'M'}${x(start+i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');
 const upper=s.prediction.map(v=>v+s.band_width),lower=s.prediction.map(v=>Math.max(0,v-s.band_width));
 const band=path(upper,272)+' '+lower.map((v,i)=>[x(272+i),y(v)]).reverse().map(([a,b])=>`L${a},${b}`).join(' ')+' Z';
 const lines=Array.from({length:5},(_,i)=>{let v=max*i/4;return `<line x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}" stroke="#26374c"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end">$${(v/1000).toFixed(0)}k</text>`}).join('');
 return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Daily spend, model forecast, weekly baseline and empirical interval. See exact final-period errors and backtest table below.">${lines}<rect x="${x(272)}" y="${T}" width="${x(last)-x(272)}" height="${H-B-T}" fill="#f6cc7006"/><path d="${band}" fill="#f6cc701b"/><path d="${path(vals,first)}" stroke="#64b6ff" stroke-width="2.1" fill="none"/><path d="${path(s.baseline,272)}" stroke="#8a9aae" stroke-width="1.5" stroke-dasharray="5 5" fill="none"/><path d="${path(s.prediction,272)}" stroke="#f6cc70" stroke-width="2.5" fill="none"/><line x1="${x(272)}" x2="${x(272)}" y1="${T}" y2="${H-B}" stroke="#697b94" stroke-dasharray="4 5"/>${[216,237,258,272,299].map(d=>`<text x="${x(d)}" y="${H-6}" text-anchor="${d===299?'end':'middle'}">${date(d)}</text>`).join('')}</svg>`;
}
function forecast(){const s=data.series[category],f=s.folds.at(-1),improvement=1-f.model_wape/f.baseline_wape;
 $('#content').innerHTML=`<div class="metrics">${metric('Transactions',n(data.transactions),'1,200 synthetic customers')}${metric('Forecast error',pct(f.model_wape),'28-day holdout · WAPE',true)}${metric('Weekly baseline error',pct(f.baseline_wape),'Repeat the last 7 observed days')}${metric('Relative error reduction',pct(improvement),'Compared with weekly baseline')}</div><section class="panel"><div class="panel-head"><h2>Daily spend / forecast holdout</h2><label class="control">Category <select id="category">${Object.keys(data.series).map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="legend"><span class="blue">Observed spend</span><span>Trend + weekday model</span><span class="gray">Weekly baseline</span><span class="band">Empirical 90% band</span></div>${chart(s)}<div class="chart-foot"><span>Forecast frozen at ${date(272)}. The next 28 days are held out.</span><span>Actual interval coverage: <b>${pct(s.coverage)}</b></span></div></section><div class="split"><section class="panel"><div class="panel-head"><h2>Walk-forward backtests</h2><span class="pill">No overlapping test windows</span></div><div class="table-wrap"><table><thead><tr><th>FORECAST START</th><th>MODEL WAPE</th><th>BASELINE WAPE</th></tr></thead><tbody>${s.folds.map(f=>`<tr><td>${date(f.cutoff)}</td><td class="num gold-text">${pct(f.model_wape)}</td><td class="num">${pct(f.baseline_wape)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>What this comparison tells us</h2><p>The model fits a trend and weekday pattern to the preceding 84 days. The weekly baseline is frozen at the same cutoff.</p><p>WAPE is total absolute error divided by total observed spend. Lower is better.</p><div class="callout">Synthetic results demonstrate the evaluation workflow. Real transaction panels require coverage, missingness, and population-shift checks.</div></section></div>`;
 $('#category').addEventListener('change',e=>{category=e.target.value;forecast()});
}
function cohort(){return data.customer_scores.filter(c=>c.risk>=threshold).sort((a,b)=>b.risk-a.risk)}
function customers(){const rows=cohort(),r=data.risk;
 $('#content').innerHTML=`<div class="metrics">${metric('Held-out ROC AUC',r.auc.toFixed(3),'Ranking across 1,074 customers',true)}${metric('Average precision',r.average_precision.toFixed(3),'Positive prevalence: '+pct(r.prevalence))}${metric('Brier score',r.brier.toFixed(3),'Prevalence baseline: '+r.baseline_brier.toFixed(3))}${metric('Top-decile lift',r.top_decile_lift.toFixed(2)+'×','Inactivity concentration')}</div><section class="panel"><div class="panel-head"><h2>Customer review queue</h2><button id="export" class="button">Export selected CSV ↓</button></div><div class="form-row"><label for="threshold">Minimum risk <input id="threshold" type="range" min="0" max="100" step="1" value="${threshold*100}"><output id="threshold-value">${pct(threshold)}</output></label><span class="pill" id="queue-size">${n(rows.length)} customers</span></div><p>Showing the first 12 selected customers. Scores use transaction history before ${date(270)}. A probability of inactivity does not measure how much an offer would help.</p><div class="table-wrap"><table><thead><tr><th>SYNTHETIC CUSTOMER</th><th>INACTIVITY RISK</th><th>DAYS SINCE PURCHASE</th><th>30-DAY SPEND</th><th>30-DAY TRANSACTIONS</th></tr></thead><tbody id="customer-rows"></tbody></table></div></section><div class="split"><section class="panel"><h2>Reliability by score band</h2><div class="table-wrap"><table><thead><tr><th>MEAN PREDICTED</th><th>OBSERVED INACTIVE</th><th>CUSTOMERS</th></tr></thead><tbody>${data.calibration.map(c=>`<tr><td>${pct(c.predicted)}</td><td>${pct(c.observed)}</td><td>${c.n}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Define the outcome first</h2><p>Inactivity means zero transactions during the 30 days after the cutoff. Eligibility requires at least one transaction in the prior 90 days.</p><p>The threshold of ${pct(r.threshold)} was selected on an earlier validation window. The slider lets you explore staffing capacity without refitting the model.</p><div class="callout">A missing purchase can reflect a switch in payment method. Permanent churn needs a separate definition and evidence.</div></section></div>`;
 updateRows();$('#threshold').addEventListener('input',e=>{threshold=+e.target.value/100;updateRows()});$('#export').addEventListener('click',()=>{const csv='synthetic_customer,inactivity_probability,days_since_purchase,spend_30d,transactions_30d\n'+cohort().map(c=>[c.id,c.risk,c.recency,c.spend,c.count].join(',')).join('\n');download(csv,'customer-review-queue.csv','text/csv')});
}
function updateRows(){const rows=cohort();$('#threshold-value').textContent=pct(threshold);$('#queue-size').textContent=n(rows.length)+' customers';$('#customer-rows').innerHTML=rows.length?rows.slice(0,12).map(c=>`<tr><td class="num">${c.id}</td><td class="gold-text num">${pct(c.risk)}</td><td>${c.recency}</td><td class="num">${money(c.spend)}</td><td>${c.count}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">No customers meet this threshold. Lower the minimum risk to expand the queue.</td></tr>'}
function experiment(){const e=data.experiment;
 $('#content').innerHTML=`<div class="metrics">${metric('Randomized participants',n(e.n),n(e.treated)+' treatment / '+n(e.control)+' control')}${metric('Incremental spend',money(e.ate),'Per assigned participant',true)}${metric('95% interval',money(e.lower)+' to '+money(e.upper),'Normal approximation · unadjusted')}${metric('Known simulated effect',money(e.true_effect),'Ground truth from generator')}</div><div class="split two"><section class="panel"><h2>Campaign economics</h2><p>Assume contribution margin and the all-in cost per assigned participant. The experiment estimates incremental spend; margin converts it to contribution.</p><div class="form-row"><label>Contribution margin <input id="margin" type="number" min="0" max="100" step="1" value="40"> %</label><label>Campaign cost <input id="cost" type="number" min="0" max="1000" step="0.25" value="${cost}"> USD</label></div><p>Estimated net contribution per participant</p><p id="net" class="large"></p><p id="net-range"></p><div id="decision" class="callout"></div></section><section class="panel"><h2>Keep assignment separate from prediction</h2><p>This is a separate 2,000-person randomized simulation. Assignment is independent of potential outcomes. The estimator is the difference in average spend by assigned treatment group.</p><p>The 95% interval uses each arm's sample variance. Campaign-cost and margin assumptions change the economics, while the measured spend effect stays fixed.</p><p>The experiment represents every randomized participant. The customer review queue is a different population; transporting this effect to that queue requires a new experiment.</p><div class="callout">Use the cost calculation to frame a pilot. Validate real effects, margins, and eligibility before committing a campaign budget.</div></section></div>`;
 const compute=()=>{const mEl=$('#margin'),cEl=$('#cost');if(mEl.value===''||cEl.value===''||!mEl.checkValidity()||!cEl.checkValidity()){$('#net').textContent='Enter valid inputs';$('#net-range').textContent='Margin: 0–100%. Cost: $0–$1,000.';$('#decision').textContent='Both inputs are required.';return}const m=+mEl.value/100;cost=+cEl.value;const net=e.ate*m-cost,low=e.lower*m-cost,high=e.upper*m-cost;$('#net').textContent=money(net);$('#net-range').textContent=`Transformed 95% interval: ${money(low)} to ${money(high)}. Break-even cost at the point estimate: ${money(e.ate*m)}.`;$('#decision').textContent=low>0?'The simulated interval is positive at these assumptions.':high<0?'The simulated interval is negative at these assumptions.':'The simulated interval crosses zero. More evidence would clarify the decision.'};['#margin','#cost'].forEach(id=>$(id).addEventListener('input',compute));compute();
}
function methods(){$('#content').innerHTML=`<div class="method-grid"><section class="panel"><h2>01 / Data-generating process</h2><p>${n(data.transactions)} synthetic transactions, 1,200 customers, 300 days from January 1, 2025. Four spending categories. Customers differ in purchase rates and wallet sizes, with weekly seasonality, a modest spending trend, and gradual exits.</p><p>These simplifications make predictive structure unusually learnable. Reported scores apply to this simulation.</p><a class="button secondary" href="synthetic-sample.csv" download>Download 2,500 example rows ↓</a></section><section class="panel"><h2>02 / Time and leakage boundaries</h2><ul><li>Training cutoff: day 150. Labels: days 150–179.</li><li>Validation cutoff: day 210. Labels: days 210–239.</li><li>Test cutoff: day 270. Labels: days 270–299.</li><li>Features use records strictly before each cutoff.</li><li>The same customer panel recurs over time. This tests later behavior of existing customers, not generalization to unseen customers.</li></ul></section><section class="panel"><h2>03 / Models and uncertainty</h2><p>Inactivity: standardized recency, frequency, spend, and frequency-change features; regularized logistic regression. Fit preprocessing on training data only.</p><p>Forecast: ridge regression on trend and weekday effects, fit to the preceding 84 days. Four non-overlapping 28-day backtests.</p><p>The 90% band uses the 90th percentile of absolute residuals from the first three backtests. Coverage is measured on the fourth; time-series dependence prevents a guaranteed coverage claim.</p></section><section class="panel"><h2>04 / Reproduce and audit</h2><pre class="mono">python -m venv .venv
source .venv/bin/activate
pip install -r requirements.txt
python analysis/build.py
python -m unittest discover -s tests
python analysis/audit.py</pre><p>Python source, exact dependency versions, SQLite audit queries, tests for time leakage and sparse histories, and generated outputs are included.</p><a href="https://github.com/Trenn1x/specforge-analyst-studio/tree/main/projects/transaction-observatory">Open the complete project ↗</a></section></div>`}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(view){if(!views[view])view='forecast';current=view;$('#view-title').textContent=views[view][0];$('#view-intro').textContent=views[view][1];document.querySelectorAll('nav button').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});({forecast,customers,experiment,methods})[view]()}
document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>{location.hash=b.dataset.view}));window.addEventListener('hashchange',()=>render(location.hash.slice(1)));render(location.hash.slice(1)||'forecast');
